"""Bets tab, generated by rule from site.json (no hand-picking).
Rules
  1. Win chance = 50/50 blend of model and market (bookmaker margin removed).
  2. A bet needs blended EV >= +5% at the posted price.
  3. Moneylines also need the model margin to beat the market handicap by >= 3 pts on that side;
     otherwise the value comes from the win-probability curve on big underdogs, not from the rating gap.
  4. Lines of 20+ points are capped at "Lean" (blowout margins are the model's least reliable area).
  5. Manual flags (documented below) can downgrade a bet to a pass; they never create one.
Two-way moneylines are draw-no-bet (draw = push).
Stakes: Bet = 1/2 of quarter-Kelly on the blended probability; Lean = 1/4 of quarter-Kelly."""
import json, numpy as np
from datetime import date
from scipy.stats import norm

SITE = '../model/site.json'
MKT = {'England': (2.0, 1e9, 1.7692, 0.5, 1.9434, 1.8621),
       'Scotland': (1.005, 1e9, 18.0, -27.5, 1.8772, 1.9259),
       'Ireland': (4.2, 1e9, 1.2083, 9.5, 1.8929, 1.9259),
       'Italy': (1.4, 1e9, 2.85, -5.5, 1.9434, 1.8621),
       'France': (1.0286, 1e9, 10.8, -19.5, 1.9259, 1.8929),
       'Wales': (2.75, 1e9, 1.4255, 5.5, 1.8929, 1.9259)}
FLAGS = {'England': 'Most of the edge comes from NZ losing to Wales with 10 changes. Remove that game and the model has England by 2, '
                    'about half the gap to the line, and the November touring trend favours NZ.'}

def amer(d): return f'+{round((d - 1) * 100)}' if d >= 2 else f'{round(-100 / (d - 1))}'
def sgn_line(team, x): return f"{team} {'+' if x > 0 else '−'}{abs(x):g}"

def build():
    d = json.load(open(SITE)); sig = d['probit']['sigma']
    bets, passes = [], []
    for m in d['matches']:
        h, a = m['home'], m['away']; o1, ox, o2, ln, oh, oa = MKT[h]; mg = -m['spread']
        s = 1 / o1 + 1 / ox + 1 / o2; t = 1 / oh + 1 / oa
        pc = 1 - norm.cdf(-ln, mg, sig)
        gap_home = mg - (-ln)                      # >0: model likes home vs the handicap
        cands = [(h, 'ML', f'{h} ML', m['p_home'], (1 / o1) / s, o1, gap_home),
                 (a, 'ML', f'{a} ML', m['p_away'], (1 / o2) / s, o2, -gap_home),
                 (h, 'HCP', sgn_line(h, ln), pc, (1 / oh) / t, oh, gap_home),
                 (a, 'HCP', sgn_line(a, -ln), 1 - pc, (1 / oa) / t, oa, -gap_home)]
        best = None
        pdraw = m['p_draw']
        for team, kind, lab, pm, pk, o, gap in cands:
            if kind == 'ML':
                # two-way ML is draw-no-bet: a draw refunds the stake. Price on win|no-draw, scale EV/Kelly by P(no draw).
                pm = pm / (1 - pdraw); nd = 1 - pdraw
            else:
                nd = 1.0
            bp = .5 * pm + .5 * pk
            ev = nd * (bp * o - 1); qk = nd * max((bp * (o - 1) - (1 - bp)) / (o - 1), 0) / 4
            row = dict(match=f'{h} v {a}', team=team, opp=a if team == h else h, kind=kind, bet=lab, am=amer(o), dec=o,
                       model=pm, mkt=pk, blend=bp, ev=ev, qk=qk, gap=gap, nd=nd, min_am=amer((1 + 0.05 / nd) / bp))
            if ev < 0.05: continue
            if kind == 'ML' and gap < 3:
                passes.append(dict(bet=f'{lab} ({amer(o)})', why=f'+{ev*100:.0f}% on paper, but the model margin is only {gap:+.1f} pts against the handicap. '
                                   'The value comes from the win-probability curve on underdogs, not the ratings.')); continue
            if best is None or row['ev'] > best['ev']: best = row
        if best is None:
            if not any(p['bet'].startswith((h, a)) for p in passes):
                passes.append(dict(bet=f'{h} v {a}', why=f'No side clears +5%. Model {sgn_line(h, round(-mg * 2) / 2)} vs market {sgn_line(h, ln)}.'))
            continue
        if best['team'] in FLAGS or best['opp'] in FLAGS:
            # `or ... and ...` without parens used to reduce to just `best['team'] in FLAGS` (operator
            # precedence: `and` binds tighter, so the opp-side check was dead code) - silently let through
            # any bet on the OTHER side of a flagged matchup, which is exactly the case this exists to catch.
            passes.append(dict(bet=f"{best['bet']} ({best['am']})", why=FLAGS.get(best['team'], FLAGS.get(best['opp'])))); continue
        best['tier'] = 'Lean' if abs(ln) >= 20 else 'Bet'
        best['why'] = (f"Model {sgn_line(h, round(-mg * 2) / 2)} vs market {sgn_line(h, ln)}: a {abs(best['gap']):.1f}-point gap.")
        if best['tier'] == 'Lean': best['why'] += ' Lean only: 20+ point lines are where the model is least reliable.'
        bets.append(best)
    tries = [dict(name=t['name'], team=t['team'], p=t['p'], bet_at=t['bet_at']) for t in sorted(d['tries'], key=lambda x: -x['p'])]
    from round_config import COMPETITION, ROUND_LABEL, ROUND_DATE
    d['betsTab'] = dict(updated=date.today().strftime('%-d %b'), round=f'{COMPETITION} · {ROUND_LABEL} · {ROUND_DATE}',
                        lines='Sportingbet board, 17 Nov',
                        bets=sorted(bets, key=lambda b: (b['tier'] != 'Bet', -b['ev'])), passes=passes, tries=tries,
                        rules='Blend 50/50 with market · +5% EV floor · moneylines need a 3-pt rating edge · 20+ pt lines capped at Lean')
    json.dump(d, open(SITE, 'w'), default=float)
    for b in d['betsTab']['bets']: print(f"{b['tier']:4s} {b['bet']:16s} {b['am']:>6s} EV {b['ev']*100:+.1f}%  stake {(b['qk']*(.5 if b['tier']=='Bet' else .25))*100:.2f}%  gap {b['gap']:+.1f}")
    for p in passes: print('PASS', p['bet'], '|', p['why'][:90])

if __name__ == '__main__':
    build()
